CurrentRates = {
    init: async function(app, container) {
        var rates = (await api.get("B2B/Rate/Current()")).value;
        var list = $("[name=rateList]", container);
        rates.forEach(rate => 
        {
            list.append("<li><label>" + rate.Name + " (" + rate.Description + ")</label><div class='value'>" + rate.Value + "%</div></li>");
        });
    }
}
